def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def leafSimilar(a, b):
    def leaves(t):
        vals, left, right = _links(t)
        out = []
        stack = [0] if vals else []
        while stack:
            k = stack.pop()
            if left[k] == -1 and right[k] == -1:
                out.append(vals[k])
            if right[k] != -1:
                stack.append(right[k])
            if left[k] != -1:
                stack.append(left[k])
        return out
    return leaves(a) == leaves(b)
